const d = decide({ conversation: conv, onDnc, addedThisRun: Boolean(input.added_this_run),
  senderKind: input.sender_kind, kind: input.kind, now: input.now, enabled: ENABLED_GUARDS });
const body = input.kind === 'template'
  ? { messaging_product: 'whatsapp', to: input.wa_id, type: 'template',
      template: { name: $env.META_TEMPLATE_NAME, language: { code: $env.META_TEMPLATE_LANG } } }
  : { messaging_product: 'whatsapp', to: input.wa_id, type: 'text', text: { body: input.text, preview_url: false } };
// The Twilio route (WA_PROVIDER=twilio, used while Meta's own number can't send) posts a form instead.
const provider = String($env.WA_PROVIDER || 'meta').toLowerCase() === 'twilio' ? 'twilio' : 'meta';
const enc = (o) => Object.entries(o).filter(([, v]) => v !== undefined && v !== null && v !== '')
  .map(([k, v]) => encodeURIComponent(k) + '=' + encodeURIComponent(String(v))).join('&');
const twilioForm = provider !== 'twilio' ? '' : enc({
  From: 'whatsapp:' + $env.TWILIO_WHATSAPP_FROM, To: 'whatsapp:+' + input.wa_id,
  ...(input.kind === 'template' ? { ContentSid: $env.TWILIO_TEMPLATE_SID } : { Body: input.text }),
  StatusCallback: $env.TWILIO_WEBHOOK_URL || String($env.WEBHOOK_URL || '').replace(/\/*$/, '/') + 'webhook/ingress-twilio',
});
