const replyMs = input.received_at ? Date.parse(now) - Date.parse(input.received_at) : null;
return [{ json: {
  now, wa_id: input.wa_id, direction: 'out', author: input.sender_kind,
  kind: failed ? 'send_error' : input.kind, text: input.text || '', route: input.route, stage: input.stage,
  classifier: input.classifier, draft: input.draft, problems: input.problems, facts_version: input.facts_version,
  input_tokens: input.input_tokens, output_tokens: input.output_tokens, reply_ms: replyMs,
